"use server";

// Generated by philote from page /services/new. Do not edit.
import { redirect } from "next/navigation";

import { services } from "@/lib/api";
import { type FormState, failed, int, text } from "@/lib/form";

export async function submit(_state: FormState, data: FormData): Promise<FormState> {
    const result = await services.create({
        name: text(data, "name"),
        minutes: int(data, "minutes"),
        price: int(data, "price"),
        about: text(data, "about"),
    });
    if (!result.ok) {
        return failed(data, result.error, result.issues);
    }
    redirect(`/services/${encodeURIComponent(result.value.id)}`);
}
